options.content:
{{#if (eq user_is_admin 0)}}
  <div style="color: #e02424; background: rgba(224, 36, 36, 0.05); border-left: 4px solid #e02424; padding: 8px 14px; font-size: 13px; display: flex; align-items: center; gap: 8px; border-radius: 2px; line-height: 1.4;">
    <span>⚠️</span>
    <span><strong>Access Denied:</strong> You must be an admin to view this page.</span>
  </div>
{{/if}}

list.definition:
SELECT CASE WHEN (u.is_admin OR EXISTS (
  SELECT 1 FROM grafana_schema.team_member tm
  JOIN grafana_schema.team t ON tm.team_id = t.id
  WHERE tm.user_id = u.id AND t.name LIKE '%\_ALL' ESCAPE '\'
)) THEN 1 ELSE 0 END
FROM grafana_schema."user" u WHERE u.id = ${__user.id}

